const cfg = $('Konfigurasi Brand1').first().json;
const names = [cfg.brand_1, cfg.brand_2, cfg.brand_3];
const items = $input.all();

const brands = names.map(name => ({ name, total_articles: 0, mentions: 0, sov: 0, articles: [] }));

items.forEach((it, i) => {
  const q = (it.json.searchParameters && it.json.searchParameters.q) || '';
  let idx = names.findIndex(n => String(n).toLowerCase() === String(q).toLowerCase());
  if (idx < 0) idx = i;
  if (idx >= brands.length) return;

  const news = it.json.news || [];
  const b = brands[idx];
  const key = String(names[idx]).toLowerCase();
  b.total_articles = news.length;

  news.forEach(n => {
    const text = ((n.title || '') + ' ' + (n.snippet || '')).toLowerCase();
    if (text.includes(key)) b.mentions++;
    b.articles.push({
      title: n.title || '',
      snippet: n.snippet || '',
      source: n.source || '',
      date: n.date || '',
      link: n.link || ''
    });
  });
});

// Share of Voice = mention brand / total mention semua brand x 100
const totalMentions = brands.reduce((s, b) => s + b.mentions, 0);
brands.forEach(b => {
  b.sov = totalMentions ? Math.round((b.mentions / totalMentions) * 1000) / 10 : 0;
});

// Susun prompt untuk AI
const corpus = brands.map(b => {
  const list = b.articles.slice(0, 15)
    .map(a => `- [${a.source}, ${a.date}] ${a.title} :: ${a.snippet}`)
    .join('\n');
  return `=== BRAND: ${b.name} (${b.mentions} mention) ===\n${list || '(tidak ada berita)'}`;
}).join('\n\n');

const prompt = `Kamu adalah analis reputasi brand dan PR senior. Analisis sentimen kumpulan berita berikut untuk ${brands.length} brand.

${corpus}

Tugas:
1. Untuk SETIAP brand, tentukan sentimen dominan (Positif/Netral/Negatif), persentase sentimen (positive_pct, neutral_pct, negative_pct, total 100), dan skor reputasi skala 1-10 (1 = sangat buruk, 10 = sangat baik).
2. Tulis 2-3 tema utama pemberitaan tiap brand dan alasan singkat skor.
3. Tulis ringkasan eksekutif (3-5 kalimat, Bahasa Indonesia) yang membandingkan semua brand, dan 3 rekomendasi strategis untuk brand pertama (${brands[0].name}).

Balas HANYA dengan JSON valid tanpa markdown, dengan format:
{"brands":[{"name":"","sentiment":"","positive_pct":0,"neutral_pct":0,"negative_pct":0,"reputation_score":0,"key_themes":["",""],"reasoning":""}],"executive_summary":"","recommendations":["","",""]}`;

return [{ json: { brands, totalMentions, prompt, generated_at: new Date().toISOString() } }];

const sov = $('Hitung SoV1').first().json;
const j = $input.first().json;
let raw = j.text || j.output || (j.content && j.content.parts && j.content.parts[0] && j.content.parts[0].text) || '{}';
raw = raw.replace(/```json|```/g, '').trim();

let ai;
try { ai = JSON.parse(raw); }
catch (e) { ai = { brands: [], executive_summary: raw, recommendations: [] }; }

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const rows = sov.brands.map((b, i) => {
  const a = (ai.brands || []).find(x => String(x.name).toLowerCase() === b.name.toLowerCase()) || (ai.brands || [])[i] || {};
  return {
    name: b.name,
    mentions: b.mentions,
    sov: b.sov,
    sentiment: a.sentiment || '-',
    pos: a.positive_pct ?? 0,
    neu: a.neutral_pct ?? 0,
    neg: a.negative_pct ?? 0,
    score: Number(a.reputation_score) || 0,
    themes: a.key_themes || [],
    reasoning: a.reasoning || ''
  };
});

const colors = ['#2563eb', '#f59e0b', '#10b981'];
const scoreColor = s => s >= 7 ? '#059669' : s >= 5 ? '#d97706' : '#dc2626';
const tanggal = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
const leader = [...rows].sort((a, b) => b.sov - a.sov)[0];

const tableRows = rows.map((r, i) => `
  <tr>
    <td><b>${esc(r.name)}</b>${i === 0 ? ' <span class="tag">Brand Anda</span>' : ''}</td>
    <td class="c">${r.mentions}</td>
    <td>
      <div class="bar"><span style="width:${r.sov}%;background:${colors[i % 3]}"></span></div>
      <b>${r.sov}%</b>
    </td>
    <td class="c">${esc(r.sentiment)}<br><small>+${r.pos}% / =${r.neu}% / -${r.neg}%</small></td>
    <td class="c"><span class="score" style="background:${scoreColor(r.score)}">${r.score}/10</span></td>
  </tr>`).join('');

const detail = rows.map((r, i) => `
  <div class="card" style="border-left:5px solid ${colors[i % 3]}">
    <h3>${esc(r.name)} <small>Skor ${r.score}/10</small></h3>
    <p><b>Tema utama:</b> ${r.themes.map(esc).join('; ') || '-'}</p>
    <p>${esc(r.reasoning)}</p>
  </div>`).join('');

const recs = (ai.recommendations || []).map(x => `<li>${esc(x)}</li>`).join('');

const html = `<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8">
<style>
  body{font-family:Arial,Helvetica,sans-serif;color:#1f2937;margin:0;padding:10px;font-size:13px}
  .header{background:#1e3a8a;color:#fff;padding:24px;border-radius:8px}
  .header h1{margin:0 0 4px;font-size:22px} .header p{margin:0;opacity:.85}
  h2{color:#1e3a8a;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-top:28px}
  .summary{background:#eff6ff;border-left:5px solid #2563eb;padding:14px 16px;border-radius:6px;line-height:1.6}
  .kpis{display:flex;gap:12px;margin-top:14px}
  .kpi{flex:1;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px;text-align:center}
  .kpi b{display:block;font-size:20px;color:#1e3a8a}
  table{width:100%;border-collapse:collapse;margin-top:10px}
  th{background:#1e3a8a;color:#fff;padding:10px;text-align:left}
  td{padding:10px;border-bottom:1px solid #e5e7eb;vertical-align:middle}
  tr:nth-child(even) td{background:#f9fafb} .c{text-align:center}
  .bar{background:#e5e7eb;border-radius:6px;height:10px;width:100%;margin-bottom:4px}
  .bar span{display:block;height:10px;border-radius:6px}
  .score{color:#fff;padding:4px 10px;border-radius:12px;font-weight:bold}
  .tag{background:#dbeafe;color:#1d4ed8;font-size:10px;padding:2px 6px;border-radius:8px}
  .card{background:#f9fafb;padding:10px 16px;margin:10px 0;border-radius:6px;page-break-inside:avoid}
  .card h3{margin:4px 0} .card small{color:#6b7280;font-weight:normal}
  .footer{margin-top:30px;text-align:center;color:#9ca3af;font-size:11px}
</style></head><body>
  <div class="header">
    <h1>Laporan Brand Monitoring &amp; Share of Voice</h1>
    <p>Dibuat otomatis pada ${tanggal} &bull; Sumber: Serper News API &bull; Analisis: AI</p>
  </div>

  <h2>Ringkasan Eksekutif</h2>
  <div class="summary">${esc(ai.executive_summary)}</div>
  <div class="kpis">
    <div class="kpi"><b>${sov.totalMentions}</b>Total Mention</div>
    <div class="kpi"><b>${esc(leader.name)}</b>SoV Tertinggi (${leader.sov}%)</div>
    <div class="kpi"><b>${rows.length}</b>Brand Dianalisis</div>
  </div>

  <h2>Tabel Perbandingan</h2>
  <table>
    <tr><th>Brand</th><th class="c">Mention</th><th>Share of Voice</th><th class="c">Sentimen</th><th class="c">Skor Reputasi</th></tr>
    ${tableRows}
  </table>

  <h2>Detail Analisis per Brand</h2>
  ${detail}

  <h2>Rekomendasi Strategis</h2>
  <ol>${recs}</ol>

  <div class="footer">Laporan otomatis dibuat dengan n8n &bull; ${tanggal}</div>
</body></html>`;

const stamp = new Date().toISOString().slice(0, 10);
const caption = `Laporan Brand Monitoring (${tanggal})\n` +
  rows.map(r => `- ${r.name}: SoV ${r.sov}%, skor ${r.score}/10`).join('\n');

return [{ json: { html, filename: `Laporan_SoV_${stamp}.pdf`, caption } }];
